public void resync() {
    emitter.renderFull();
    // A's own emitter does not carry the origin subtree (it is forwarded), so a
    // client resync must also refresh the proxy regions from their origins.
    ProxyHost host = proxyHost;
    if (host != null) {
        host.resyncAll();
    }
    batcher.flush();
}

